-- Historical JYC event archive expansion sourced from official JIIT publications.
with seed(slug,title,event_type,start_at,end_at,venue,description,source_url) as (
  select * from jsonb_to_recordset('[{"slug":"jaypee-youth-parliament-2013","title":"Jaypee Youth Parliament 2013","event_type":"Literary / Public Affairs","start_at":"2013-10-12T09:00:00+05:30","end_at":"2013-10-13T18:00:00+05:30","venue":"JIIT Noida","description":"Inter-college parliamentary simulation organized through the JYC literary ecosystem.","source_url":"https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf"},{"slug":"extempore-national-education-day-2013","title":"Extempore · National Education Day 2013","event_type":"Literary","start_at":"2013-11-13T10:00:00+05:30","end_at":"2013-11-13T18:00:00+05:30","venue":"JIIT Noida","description":"Extempore activity held around Maulana Azad and National Education Day.","source_url":"https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf"},{"slug":"campus-green-impressions-2014","title":"Campus Green · Impressions 2014","event_type":"Environment / Awareness","start_at":"2014-03-30T10:00:00+05:30","end_at":"2014-04-01T18:00:00+05:30","venue":"JIIT Noida","description":"Environment-awareness activity organized during Impressions 2014.","source_url":"https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf"},{"slug":"scavenger-hunt-impressions-2014","title":"Scavenger Hunt · Impressions 2014","event_type":"Technical / Puzzle","start_at":"2014-03-30T10:00:00+05:30","end_at":"2014-04-01T18:00:00+05:30","venue":"JIIT Noida","description":"Clue-based technical mystery challenge from the 2014 JYC programme.","source_url":"https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf"},{"slug":"microbe-premier-league-2014","title":"Microbe Premier League · Impressions 2014","event_type":"Technical / Biotechnology","start_at":"2014-03-30T10:00:00+05:30","end_at":"2014-04-01T18:00:00+05:30","venue":"JIIT Noida","description":"Virtual industry strategy challenge built around microbes, money and turnover.","source_url":"https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf"},{"slug":"merge-and-sketch-impressions-2014","title":"Merge & Sketch · Impressions 2014","event_type":"Creative / Art","start_at":"2014-03-30T10:00:00+05:30","end_at":"2014-04-01T18:00:00+05:30","venue":"JIIT Noida","description":"Sketching-hub creative event held during Impressions 2014.","source_url":"https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf"},{"slug":"conventional-rangoli-impressions-2014","title":"Conventional Rangoli · Impressions 2014","event_type":"Creative / Culture","start_at":"2014-03-08T10:00:00+05:30","end_at":"2014-03-09T18:00:00+05:30","venue":"JIIT Noida","description":"Major rangoli event from the Kalakriti contribution to Impressions 2014.","source_url":"https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf"},{"slug":"ebullience-2018","title":"Ebullience 2018","event_type":"Fresher’s Welcome","start_at":"2018-09-01T10:00:00+05:30","end_at":"2018-09-01T22:00:00+05:30","venue":"JIIT Noida","description":"Grand fresher welcome featuring dance, food, fashion, performances and Mr. & Ms. Ebullience.","source_url":"https://www.jiit.ac.in/sites/default/files/JIIT%20NewsLetter%20Vol%204%20Issue1.pdf"}]'::jsonb) as x(slug text,title text,event_type text,start_at text,end_at text,venue text,description text,source_url text)
)
insert into public.jyc_events(slug,title,event_type,start_at,end_at,venue,short_description,featured,pinned,status)
select slug,title,event_type,start_at::timestamptz,end_at::timestamptz,venue,description,false,false,'past'
from seed where not exists(select 1 from public.jyc_events e where e.slug=seed.slug);

with seed(slug,source_url) as (
  values
  ('jaypee-youth-parliament-2013','https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf'),
