  ('microbe-premier-league-2014','https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf'),
  ('merge-and-sketch-impressions-2014','https://www.jiit.ac.in/sites/all/themes/ibees/images/pdf/JIITAnnual-Report.pdf'),
