insert into public.jyc_content_verification(entity_type,entity_id,campus_id,status,source_type,source_url,notes)
select 'event',seed.slug,'sector-128','review','official-institute-archive',seed.source_url,'Historical event record reconstructed from official JIIT publication.'
from seed where not exists(select 1 from public.jyc_content_verification cv where cv.entity_type='event' and cv.entity_id=seed.slug);